import itertools
from itertools import combinations

def check_independent_set(adj, n):
    """Return the size of the maximum independent set."""
    max_is = 0
    for size in range(n, 0, -1):
        for subset in combinations(range(n), size):
            independent = True
            for u, v in combinations(subset, 2):
                if adj[u][v]:
                    independent = False
                    break
            if independent:
                max_is = max(max_is, size)
                return max_is  # since we go from large to small
    return max_is

def max_independent_set_size(adj, n):
    """Return the size of the maximum independent set."""
    for size in range(n, 0, -1):
        for subset in combinations(range(n), size):
            independent = True
            for u, v in combinations(subset, 2):
                if adj[u][v]:
                    independent = False
                    break
            if independent:
                return size
    return 0

def vertex_connectivity(adj, n):
    """Compute vertex connectivity using max-flow."""
    from collections import defaultdict, deque

    def bfs_capacity(cap, source, sink, parent):
        visited = set([source])
        queue = deque([source])
        while queue:
            u = queue.popleft()
            for v in range(len(cap)):
                if v not in visited and cap[u][v] > 0:
                    visited.add(v)
                    parent[v] = u
                    if v == sink:
                        return True
                    queue.append(v)
        return False

    def max_flow(cap, source, sink):
        N = len(cap)
        parent = [-1] * N
        flow = 0
        while bfs_capacity(cap, source, sink, parent):
            path_flow = float('inf')
            s = sink
            while s != source:
                u = parent[s]
                path_flow = min(path_flow, cap[u][s])
                s = parent[s]
            flow += path_flow
            v = sink
            while v != source:
                u = parent[v]
                cap[u][v] -= path_flow
                cap[v][u] += path_flow
                v = parent[v]
            parent = [-1] * N
        return flow

    # Node splitting: each node i -> i_in (i) and i_out (i+n)
    # Edge i_in -> i_out with capacity 1 (for internal nodes)
    # Edge u_out -> v_in with capacity inf (for graph edges)

    min_cut = float('inf')

    for s in range(n):
        for t in range(n):
            if s == t:
                continue
            if not adj[s][t]:
                # Only need to check non-adjacent pairs for connectivity
                # Build flow network with node splitting
                N = 2 * n
                cap = [[0] * N for _ in range(N)]

                for i in range(n):
                    if i == s or i == t:
                        cap[i][i + n] = n  # source and sink have infinite capacity
                    else:
                        cap[i][i + n] = 1  # internal nodes have capacity 1

                for u in range(n):
                    for v in range(n):
                        if adj[u][v]:
                            cap[u + n][v] = n  # edges have infinite capacity
                            cap[v + n][u] = n

                flow = max_flow(cap, s + n, t)  # s_out to t_in
                min_cut = min(min_cut, flow)

    return min_cut if min_cut != float('inf') else n

