import itertools
from itertools import combinations
from collections import deque

def max_independent_set_size(adj, n):
    for size in range(n, 0, -1):
        for subset in combinations(range(n), size):
            independent = True
            for u, v in combinations(subset, 2):
                if adj[u][v]:
                    independent = False
                    break
            if independent:
                return size
    return 0

def vertex_connectivity(adj, n):
    def bfs(cap, source, sink, parent):
        visited = set([source])
        queue = deque([source])
        while queue:
            u = queue.popleft()
            for v in range(len(cap)):
                if v not in visited and cap[u][v] > 0:
                    visited.add(v); parent[v] = u
                    if v == sink: return True
                    queue.append(v)
        return False
    def maxflow(cap, s, t):
        N = len(cap); parent = [-1]*N; flow = 0
        while bfs(cap, s, t, parent):
            pf = float('inf'); v = t
            while v != s: u = parent[v]; pf = min(pf, cap[u][v]); v = u
            flow += pf; v = t
            while v != s: u = parent[v]; cap[u][v] -= pf; cap[v][u] += pf; v = u
            parent = [-1]*N
        return flow
    mc = float('inf')
    for s in range(n):
        for t in range(n):
            if s == t or adj[s][t]: continue
            N = 2*n; cap = [[0]*N for _ in range(N)]
            for i in range(n): cap[i][i+n] = n if i in (s,t) else 1
            for u in range(n):
                for v in range(n):
                    if adj[u][v]: cap[u+n][v] = n
            mc = min(mc, maxflow(cap, s+n, t))
    return mc if mc != float('inf') else n

